"""Playwright tests for the Latin layer (study-bible-latin). Usage: serve site/ (e.g. python3 -m http.server 8766), then python3 build/test_latin.py [base-url] [shots-dir]"""
import json, sys, os, urllib.request
from playwright.sync_api import sync_playwright
B = sys.argv[1] if len(sys.argv) > 1 else 'http://localhost:8766/'
S = sys.argv[2] if len(sys.argv) > 2 else '/workspace/lxx-nt/test/shots/latin_'
os.makedirs(os.path.dirname(S), exist_ok=True)
errs, fails = [], []
def check(c, m): (None if c else fails.append(m)); print(('PASS ' if c else 'FAIL ') + m)
def mode(p, m): p.locator(f'.modebar [data-mode="{m}"]').first.click(); p.wait_for_timeout(500)
with sync_playwright() as pw:
    br = pw.chromium.launch()
    for name, vp in [('phone', {'width': 360, 'height': 800}), ('desktop', {'width': 1280, 'height': 900})]:
        p = br.new_page(viewport=vp, device_scale_factor=2 if name == 'phone' else 1)
        p.on('pageerror', lambda e: errs.append(str(e))); p.on('console', lambda m: m.type == 'error' and errs.append(m.text))
        p.goto(B + '#/Gen/1'); p.wait_for_selector('.w')
        check(p.locator('.modebar button').count() == 5, f'{name}: five modes')
        mb = p.locator('.modebar').bounding_box(); check(mb['x'] >= 0 and mb['x'] + mb['width'] <= vp['width'] + 1, f'{name}: mode bar fits the screen ({int(mb["width"])}px)')
        # Greek card: Latin line only for a confident match
        p.locator('#v1 .w', has_text='θεὸς').first.click(); p.wait_for_selector('#sla:not([hidden])'); t = p.inner_text('#sla')
        check('Deus' in t and 'automatic match' in t, f'{name}: Greek card θεὸς shows Vulgate Deus ({t!r})')
        p.keyboard.press('Escape'); p.locator('#v1 .w', has_text='ἀρχῇ').first.click(); p.wait_for_selector('#panel:not([hidden]) .sum'); p.wait_for_timeout(900)
        check(p.locator('#sla').is_hidden(), f'{name}: no Latin line where the match is not confident (ἀρχῇ)'); p.keyboard.press('Escape')
        mode(p, 'latin'); p.wait_for_selector('.lverse')
        check(p.locator('.en.dr').first.is_hidden() and 'In principio' in p.inner_text('.lverse >> nth=0'), f'{name}: Latin mode shows the Vulgate only')
        p.locator('.lw', has_text='Deus').first.click(); p.wait_for_selector('#panel:not([hidden]) .sum.lat'); t = p.inner_text('#panelBody')
        check('deus' in t and 'God' in t and 'hand-checked' in t and 'noun' in t, f'{name}: Latin card Deus: lemma, hand-checked meaning, parse')
        p.screenshot(path=f'{S}{name}_latin_gen1_deus.png'); p.keyboard.press('Escape')
        mode(p, 'latin-en'); p.wait_for_selector('.en.dr'); check('In the beginning God created' in p.inner_text('.lverse >> nth=0'), f'{name}: Latin + English (Douay-Rheims)')
        p.screenshot(path=f'{S}{name}_latin_en_gen1.png')
        mode(p, 'latin-gk'); p.goto(B + '#/Ps/22'); p.wait_for_selector('.verse.pair')
        check(p.locator('.verse.pair .gk').count() > 3 and p.locator('.verse.pair .la').count() > 3, f'{name}: Latin + Greek pairs verses (Ps 22)')
        p.screenshot(path=f'{S}{name}_latin_gk_ps22.png')
        p.goto(B + '#/Tob/1'); p.wait_for_selector('.lverse'); check(p.locator('.verse.pair').count() == 0 and 'Aramaic' in p.inner_text('#main'), f'{name}: Tobit is single-text with a note')
        for bk in ('Jdt/1', 'Sir/1', 'Jer/1'):
            p.goto(B + '#/' + bk); p.wait_for_selector('.lverse'); check(p.locator('.verse.pair').count() == 0, f'{name}: {bk} single-text in Latin + Greek')
        p.goto(B + '#/Prov/31'); p.wait_for_selector('.lverse'); check('Proverbs 30' in p.inner_text('h1') and 'Proverbs 31' in p.inner_text('h1'), f'{name}: content map: our Prov 31 shows Vulgate Prov 30 + 31')
        p.goto(B + '#/4Esdr/1'); p.wait_for_selector('.lverse'); t = p.inner_text('#main')
        check('There is no Greek text for this book.' in t and 'papyr' not in t.lower() and 'not included yet' not in t and 'not been proofread' not in t and p.locator('.lmiss').count() == 0, f'{name}: 4 Esdras: Latin shown; note says only that there is no Greek text')
        check('Liber Esdræ prophetæ secundus' in t and p.locator('.lverse').count() == 40, f'{name}: 4 Esdras 1: Latin, 40 verses ({p.locator(".lverse").count()})')
        mode(p, 'latin-en'); p.goto(B + '#/4Esdr/16'); p.wait_for_selector('.lverse .en.kjv'); t = p.inner_text('#main')
        check(p.locator('.lverse').count() == 78 and 'King James' in p.get_attribute('.en.kjv >> nth=0', 'title') and 'King James Version' in t and 'Douay' not in t, f'{name}: 4 Esdras 16: 78 KJV-cut verses with the KJV English')
        if name == 'phone': p.goto(B + '#/4Esdr/1'); p.wait_for_selector('.lverse .en.kjv'); p.screenshot(path=f'{S}{name}_4esdras_1.png')
        p.goto(B + '#/PrMan/1'); p.wait_for_selector('.lverse .en.kjv'); check(p.locator('.lverse').count() == 15 and 'Domine omnipotens' in p.inner_text('#main') and 'O Lord, Almighty God' in p.inner_text('#main'), f'{name}: Prayer of Manasseh: Latin + KJV English (15 verses)')
        mode(p, 'latin-gk'); p.goto(B + '#/1Esdr/8'); p.wait_for_selector('.verse.pair'); t40 = p.inner_text('#v40')
        check(p.locator('.verse.pair .la:not(.none)').count() >= 90 and 'Not in the Vulgate' in t40 and 'Βαγὼ' in t40, f'{name}: 3 Esdras 8: Latin beside the Greek; 8:40 has the not-in-the-Vulgate note')
        p.goto(B + '#/1Esdr/1'); p.wait_for_selector('#v1 .la'); check('Et fecit Iosias Pascha' in p.inner_text('#v1'), f'{name}: 3 Esdras 1:1 Latin paired with Greek 1:1')
        p.goto(B + '#/Joel/3'); p.wait_for_selector('.verse.pair .la'); t = p.inner_text('#main')
        check(p.locator('.lmiss').count() == 0 and 'Vulgate and KJV number these Joel 2:28–32.' in p.inner_text('.vnote') and p.locator('.verse.pair .la:not(.none)').count() == 5 and 'Et erit post hæc' in p.inner_text('#v1'), f'{name}: Joel 3 follows the Greek: Vulgate 2:28–32 beside Greek 3:1–5 with the note')
        if name == 'phone': p.screenshot(path=f'{S}{name}_joel3.png')
        p.goto(B + '#/Joel/2'); p.wait_for_selector('.verse.pair'); nums = p.eval_on_selector_all('.la .vn', 'e => e.map(x => x.textContent)')
        check(nums[-1] == '27' and 'Et erit post hæc' not in p.inner_text('#main'), f'{name}: Joel 2 ends at 2:27 (2:28–32 moved to Joel 3) ({nums[-3:]})')
        mode(p, 'latin-en'); p.goto(B + '#/Joel/3'); p.wait_for_selector('.lverse .en'); check('pour out my spirit' in p.inner_text('#main'), f'{name}: Joel 3 in Latin + English shows the Douay English of 2:28–32')
        p.goto(B + '#/Ps/151'); p.wait_for_selector('.lmiss'); check('Psalm 151 is not in the Vulgate' in p.inner_text('.lmiss'), f'{name}: Psalm 151 unchanged (not in the Vulgate)')
        p.goto(B + '#/3Macc/1'); p.wait_for_selector('.lmiss'); check('not in the Vulgate' in p.inner_text('.lmiss'), f'{name}: 3 Maccabees: not-in-Vulgate note')
        p.goto(B + '#/PrMan/1'); p.wait_for_selector('h1'); check('Prayer of Manasseh (Odes 12)' in p.inner_text('h1'), f'{name}: PrMan title')
        mode(p, 'reader'); p.goto(B + '#/Tob/1'); p.wait_for_selector('.w'); p.locator('.w').nth(3).click(); p.wait_for_selector('#panel:not([hidden]) .sum'); p.wait_for_timeout(800)
        check(p.locator('#sla').is_hidden(), f'{name}: no Latin line in the Greek card for Tobit'); p.keyboard.press('Escape')
        p.goto(B + '#/'); p.wait_for_selector('#hs1'); names = [x.inner_text().split('\n')[0] for x in p.locator('#hs1 .bn').all()]
        check(len(names) > 2 and names[0].startswith('1 Esdras') and names[1].startswith('4 Esdras'), f'{name}: home: 4 Esdras right after 1 Esdras ({names[:3]})')
        check(any('Prayer of Manasseh (Odes 12)' in n for n in names) and p.locator('.hsec').count() == 3, f'{name}: home: three sections, PrMan named')
        p.screenshot(path=f'{S}{name}_home.png', full_page=False)
        p.goto(B + '#/search?q=verbum'); p.wait_for_selector('.lres'); p.locator('.lres').first.click(); p.wait_for_selector('#results .refs a')
        p.locator('#results .refs a').first.click(); p.wait_for_selector('.lw.same'); check(p.locator('.lw.same').count() >= 1, f'{name}: Latin search → verse with the word marked')
        mode(p, 'reader'); p.close()
    # 'Also in' on the Latin card: links for content words, hidden for common words (UPOS + explicit list)
    import re
    p = br.new_page(viewport={'width': 412, 'height': 915}); p.on('pageerror', lambda e: errs.append(str(e)))
    p.goto(B + '#/Gen/1'); p.wait_for_selector('.w'); mode(p, 'latin'); p.wait_for_selector('.lverse')
    for wtxt in ('et', 'In', 'super'):
        p.keyboard.press('Escape'); p.locator('.lw', has_text=re.compile('^' + wtxt + '$')).first.click(); p.wait_for_selector('#panel:not([hidden]) .sum.lat'); p.wait_for_timeout(900)
        check(p.locator('#latAlso').is_hidden(), f'Latin card: no Also in for common word {wtxt!r}')
    p.keyboard.press('Escape'); p.locator('.lw', has_text=re.compile('^terram$')).first.click(); p.wait_for_selector('#latAlso:not([hidden]) a.also')
    hrefs = p.eval_on_selector_all('#latAlso a.also', 'e => e.map(a => a.getAttribute("href"))')
    check(1 <= len(hrefs) <= 3 and all(re.fullmatch(r'#/\w+/\w+/L\w+_\d+_\d+\?llex=\d+', h) for h in hrefs), f'Latin card: terra has tappable Also in passages ({hrefs})')
    p.screenshot(path=f'{S}phone_latin_card_also_in.png')
    p.click('#latAlso a.also >> nth=0'); p.wait_for_selector('.lw.same'); p.wait_for_timeout(300)
    check(p.url.endswith(hrefs[0]) and p.locator('.lw.same').count() >= 1, 'Latin Also in link opens the chapter with the word marked')
    p.go_back(); p.wait_for_selector('#panel:not([hidden]) .sum.lat'); p.wait_for_timeout(300)
    check(p.url.endswith('#/Gen/1') and 'terra' in p.inner_text('#panelBody'), 'Latin: back returns to Gen 1 with the terra card open')
    # Descendants on the Latin card: exact dictionary form (u/v spelling allowed), absent row when Wiktionary has no list
    p.goto(B + '#/Gen/1'); p.wait_for_selector('.lverse')
    p.keyboard.press('Escape'); p.locator('.lw', has_text=re.compile('^terram$')).first.click(); p.wait_for_selector('#ldescRow:not([hidden])'); t = p.text_content('#ldescRow')
    check('Italian terra' in t and 'Wiktionary · CC BY-SA 4.0' in t, f'Latin card terra: Descendants from Wiktionary ({t[:80]!r})')
    p.keyboard.press('Escape'); p.locator('.lw', has_text=re.compile('^unus$')).first.click(); p.wait_for_selector('#panel:not([hidden]) .sum.lat'); p.wait_for_timeout(900)
    check(p.locator('#ldescRow').is_hidden() and 'Descendants' not in p.inner_text('#panelBody'), 'Latin card unus (no unambiguous list): no Descendants section')
    mode(p, 'reader'); p.close()
    # Latin pass v2: meaning from context, KJV name spellings, quæ, Whitaker credit, held tokens stay blank
    ST = json.load(open('build/lcx_stats.json'))
    check(ST['context'] + ST['context_tutor'] == 63825 and ST['name_new'] == 13503 and ST['name_existing_card'] == 17543 and ST['quae_relative'] == 2922 and ST['quae_interrogative'] == 79 and ST['link'] == 2742,
          f'Latin pass v2 counts: {ST["context"] + ST["context_tutor"]} context meanings, {ST["name_new"]}+{ST["name_existing_card"]} names, quæ {ST["quae_relative"]}/{ST["quae_interrogative"]}, {ST["link"]} links')
    check(ST['held_probable'] == 11863 and ST['held_both'] == 10 and ST['held_flagged'] == 1, 'Latin pass v2: held tokens (neighbour check / invalid headword, both readings, flagged) left blank')
    p = br.new_page(viewport={'width': 412, 'height': 915}); p.on('pageerror', lambda e: errs.append(str(e)))
    p.goto(B + '#/Matt/17'); p.wait_for_selector('.w'); mode(p, 'latin'); p.goto(B + '#/Matt/17/2'); p.wait_for_selector('.lw.cx')
    p.locator('#vLMAT_17_2 .lw[data-i="16"]').click(); p.wait_for_selector('#panel:not([hidden]) .sum.lat'); p.wait_for_timeout(500); t = p.inner_text('#panelBody')
    check('albus' in t and 'white' in t and 'meaning from context' in t and 'Whitaker' in t, f'Latin card alba (Matt 17:2): albus, “white”, labelled meaning from context ({t[:120]!r})')
    p.screenshot(path=f'{S}phone_latin_meaning_from_context.png')
    p.goto(B + '#/Gen/28'); p.wait_for_selector('#vLGEN_28_2 .lw'); p.keyboard.press('Escape'); p.locator('#vLGEN_28_2 .lw[data-i="9"]').click(); p.wait_for_selector('#panel:not([hidden]) .sum.lat'); p.wait_for_timeout(400); t = p.inner_text('#panelBody')
    check('Bethuel' in t and 'KJV spelling' in t, f'Latin card name: KJV spelling (Gen 28:2 Bathuel → Bethuel) ({t[:80]!r})')
    LX = json.load(urllib.request.urlopen(B + 'data/lcx/GEN/35.json')); bethel = [e for v in LX.values() for e in v.values() if e[0] == 'n' and e[2] == 'Beth-el']
    check(len(bethel) >= 1, f'Latin names keep the KJV hyphen (Beth-el, Gen 35) ({len(bethel)})')
    sir = json.load(urllib.request.urlopen(B + 'data/lcx/SIR/39.json')); vs = json.load(urllib.request.urlopen(B + 'data/vul/SIR/39.json')); r19 = [r for r in vs if r[0] == 19][0]
    fi = [i for i, t in enumerate(r19[3]) if t[0] == 'Florete']; check(fi and str(fi[0]) not in sir.get('19', {}), 'Latin pass v2: a flagged token (Sir 39:19 Florete) stays blank')
    QA = [e for f in ('1SA/28', 'PSA/118', 'ISA/1') for v in json.load(urllib.request.urlopen(B + f'data/lcx/{f}.json')).values() for e in v.values() if e[0] == 'q']
    check(QA and {e[2] for e in QA} <= {'who, which, that', 'what? which? who?'}, f'quæ → qui with one combined meaning, questions “what? which? who?” ({ {e[2] for e in QA} })')
    p.goto(B + '#/about'); p.wait_for_selector('article'); check('Whitaker' in p.inner_text('article') and 'Lewis' in p.inner_text('article'), 'About: Whitaker’s Words credited next to Lewis & Short')
    mode(p, 'reader') if p.locator('.modebar').count() else None; p.close()
    bk = json.load(urllib.request.urlopen(B + 'data/books.json'))
    check(not any(b.get('latinOnly') and os.path.exists('data/' + b['id']) for b in bk), 'latin-only books have no Greek chapter files (expected)')
    check(not errs, f'no JS errors {errs[:3]}')
print(f'{len(fails)} failed'); sys.exit(1 if fails else 0)
